void quicksort(int* values, int low, int high)
{
  if (low >= high)
    return;

  // Use a mutable pointer to avoid copying the array.
  int* pivot = values + low;
  int* start = values + low;
  int* end = values + high;

  // Partition the array around the pivot.
  int pivot_val = *pivot;
  while (start < end) {
    while (start < end && *start <= pivot_val) {
      ++start;
    }
    while (start < end && *end > pivot_val) {
      --end;
    }
    if (start < end) {
      std::swap(*start, *end);
    }
  }

  // Place the pivot in its correct position.
  std::swap(*pivot, *start);

  // Recursively sort the two sub‑arrays.
  quicksort(values, low, start - 1);
  quicksort(values, start + 1, high);
}

