  quicksort(values, split + 1, high);
}

void fill(int** grid, int row, int col, int from, int to)
{
  // Guard against null pointer or invalid coordinates.
  if (!grid || row < 0 || col < 0 || grid[row][col] != from)
    return;

  // Replace the target cell with the replacement value.
  grid[row][col] = to;

  // Recursively fill the four orthogonal neighbors.
  fill(grid, row + 1, col, from, to);
  fill(grid, row - 1, col, from, to);
  fill(grid, row, col + 1, from, to);
  fill(grid, row, col - 1, from, to);
}

void fill(int** grid, int row, int col, int from, int to)
{
  // Guard against null pointer or invalid indices.
  if (!grid || row < 0 || col < 0 || grid[row][col] != from)
    return;

  // Store the original value to restore later.
  const int original = grid[row][col];

  // Replace the target cell with the replacement value.
  grid[row][col] = to;

  // Recursively fill the four adjacent cells.
  fill(grid, row + 1, col, from, to);
  fill(grid, row - 1, col, from, to);
  fill(grid, row, col + 1, from, to);
  fill(grid, row, col - 1, from, to);

  // Restore the original value to preserve the original grid.
  grid[row][col] = original;
}

void fill(int** grid, int row, int col, int from, int to)
{
  static std::unordered_map<std::pair<int,int>, bool> memo;
  static std::unordered_map<std::pair<int,int>, int> memo2;

  auto key = std::make_pair(row, col);
  if (memo.count(key))
    return;

  if (row < 0 || col < 0 || grid[row][col] != from)
    return;

  grid[row][col] = to;
  memo[key] = true;

  fill(grid, row + 1, col, from, to);
  fill(grid, row - 1, col, from, to);
  fill(grid, row, col + 1, from, to);
  fill(grid, row, col - 1, from, to);
}

void fill(int** grid, int row, int col, int from, int to)
{
  if (row < 0 || col < 0 || !grid || !grid[row] || grid[row][col] != from)
    return;

  grid[row][col] = to;

  // Directions: right, left, up, down
  const int dx[] = {0, 0, -1, 1};
  const int dy[] = {1, -1, 0, 0};

  for (int dir = 0; dir < 4; ++dir)
  {
    int newRow = row + dx[dir];
    int newCol = col + dy[dir];

    if (newRow >= 0 && newCol >= 0 && newRow < static_cast<int>(std::size(grid)) && newCol < static_cast<int>(std::size(grid[0])) && grid[newRow][newCol] == from)
    {
      fill(grid, newRow, newCol, from, to);
    }
  }
